ote_status in (''customer_confirmed'',''platform_charged'',''waived'') and scoped.total_amount>=0 then scoped.total_amount else null::numeric end,\n      ''shipping_quote_status'',scoped.shipping_quote_status,\n      ''delivery_status'',scoped.delivery_status,\n      ''express_quote'',k2_private.project_express_quote_v1(scoped.id),\n      ''item_count'',coalesce((\n        select sum(line.quantity)::integer\n        from public.order_request_items line\n        where line.order_request_id=scoped.id\n      ),0),\n      ''created_at'',scoped.created_at\n    ) order by scoped.created_at desc)\n    from (\n      select request.* from public.order_requests request\n      join public.guest_access_grant_scopes s\n        on s.scope_kind=''order_request'' and s.scope_id=request.id\n      where s.grant_id=v_grant.id and ''read''=any(s.permissions)\n      order by request.created_at desc limit 20\n    ) scoped\n  ),''[]''::jsonb);\nend;\n","acl":["postgres=X/postgres","anon=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.list_customer_account_history_v1(bigint, uuid, text, text, text)","before":"1a97473f50de0a4542cb7c53b4a05793201508689da74251a8793c6bcff45fd1","after":"aeca7c9ba8a0c8871ecdcab086943bace5c731731297559f84150eee08fe327b","body":"\ndeclare\n  v_account public.customer_accounts;\n  v_rate record;\nbegin\n  if auth.uid() is null then\n    return query select false,''ACCOUNT_AUTH_REQUIRED'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  if not k2_private.verify_guest_bff_request(\n    ''account_read'',p_timestamp,p_nonce,p_payload_text,p_ip_hash,p_signature\n  ) then\n    return query select false,''REQUEST_REPLAYED'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  if p_payload_text <> ''{}'' then\n    return query select false,''REQUEST_INVALID'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  select * into v_account from pub